import {catalog} from './catalog.js';
export const cash=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
export function totalCost(item,tax=0){return Number(item.price||0)*(1+Number(tax||0)/100)+Number(item.delivery||0)+Number(item.assembly||0);}
export function fitCheck(item,space){const dims=[item.width,item.depth,item.height].map(Number);if(dims.some(n=>!Number.isFinite(n)||n<=0))return 'Add all three item dimensions';const [w,d]=[space.width,space.depth].map(Number);if(!w||!d)return 'Add room dimensions';const footprint=(dims[0]<=w&&dims[1]<=d)||(dims[1]<=w&&dims[0]<=d);if(!footprint)return 'Footprint exceeds room dimensions';if(Number(space.door)>0&&Math.min(...dims)>Number(space.door))return 'Access warning: smallest item side exceeds opening';return 'Footprint fits; check clearance, packaging and turning space';}
export function validateBoard(b){return b&&Array.isArray(b.items)&&b.items.length<=100&&b.items.every(i=>i&&typeof i.id==='string'&&typeof i.name==='string'&&i.name.length<300&&['price','delivery','assembly','width','depth','height','resale','requiredDepth'].every(k=>i[k]==null||i[k]===''||Number.isFinite(Number(i[k]))&&Number(i[k])>=0)&&(!i.contributions||Object.values(i.contributions).every(n=>Number.isFinite(Number(n))&&Number(n)>=0)))&&Array.isArray(b.people)&&b.people.length>0&&b.people.length<=12&&b.people.every(n=>typeof n==='string'&&n.length<=100&&!['__proto__','constructor','prototype'].includes(n))&&Number.isFinite(Number(b.budget))&&Number(b.budget)>=0&&Number.isFinite(Number(b.tax))&&Number(b.tax)>=0&&Number(b.tax)<=30;}

const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='roomedit-board-v2';let state={items:[],people:['Me'],budget:2500,tax:0,space:{},purpose:'living',horizon:'long'};try{const saved=JSON.parse(localStorage.getItem(key));if(validateBoard(saved))state={...state,...saved};}catch{}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));}catch{status('This browser could not save your board. Export a copy.');}}
function status(t){$('#board-status').textContent=t;}
const nav=document.querySelector('.mode-tabs');nav.insertAdjacentHTML('beforeend','<button id="board-tab" aria-pressed="false">Room board & move plan</button>');
const section=document.createElement('section');section.id='board-mode';section.hidden=true;document.querySelector('footer').before(section);
section.innerHTML=`<p class="eyebrow">MAKE THE WHOLE DECISION</p><h1>Your room, worked out.</h1><p class="intro">Compare costs, plan with roommates and find a place for what you already own.</p><div class="board-layout"><aside><h2>Your brief</h2><label>What is this room for?<select id="purpose"><option value="living">Relaxing & hosting</option><option value="work">Working from home</option><option value="sleep">Sleeping</option><option value="small">Small-space living</option></select></label><label>How long will you keep it?<select id="horizon"><option value="long">Long-term home</option><option value="short">Under a year / frequent moves</option></select></label><label>Room budget (USD)<input id="room-budget" type="number" min="0" max="1000000"></label><label>Estimated tax rate (%)<input id="tax-rate" type="number" min="0" max="30" step=".01"></label><label>Household names (comma separated)<input id="people" maxlength="200"></label><p class="note">Votes and contributions are entered by your household. Shared links are snapshots, not live collaborative editing.</p><h3>Room & access · inches</h3><label>Room width<input id="room-width" type="number" min="1"></label><label>Room depth<input id="room-depth" type="number" min="1"></label><label>Narrowest door / elevator opening<input id="room-door" type="number" min="1"></label><label>Access notes<textarea id="access" placeholder="Third-floor walk-up, elevator booking, stair turns…" maxlength="1000"></textarea></label><button class="primary" id="apply-brief">Save brief</button><button class="secondary" id="starter">Build a budget starter set</button><p class="note">Starter sets select low-cost catalog pieces for your purpose. Delivery, assembly, ergonomics and stock need checking.</p></aside><div><div class="board-actions"><button id="add-item">+ Add a listing or owned piece</button><button id="share-board">Copy snapshot link</button><button id="export-board">Export board</button><label class="import-label">Import board<input id="import-board" type="file" accept="application/json" hidden></label></div><p id="board-status" role="status"></p><div id="board-summary"></div><div class="board-actions"><label>Show<select id="board-filter"><option value="all">All pieces</option><option value="buy">Shopping shortlist</option><option value="owned">Already owned / move-out</option><option value="used">Secondhand & unique finds</option></select></label></div><div id="board-items"></div><details><summary>Before you buy or arrange pickup</summary><p>Confirm current availability with the seller, ask for current photos and condition details, compare materials and returns, and agree on pickup timing. A saved listing is not a verified seller or booking.</p><p>For delivery, confirm curbside versus in-room service, stair fees, elevator rules, payment methods, shipping thresholds and return costs with the retailer.</p></details></div></div><dialog id="item-dialog"><form id="item-form"><h2 id="item-title">Add a piece</h2><div class="edit-grid"><label>Name<input name="name" required maxlength="200"></label><label>Source<select name="source"><option value="new">New retail listing</option><option value="used">Secondhand / unique find</option><option value="owned">Already owned</option></select></label><label>Category<select name="category">${['sofa','chair','table','desk','bed','storage','rug','lamp','other'].map(v=>`<option>${v}</option>`).join('')}</select></label><label>Listed / purchase price $<input name="price" type="number" min="0" max="1000000" step=".01" required></label><label>Product link<input name="url" type="url" placeholder="https://…"></label><label>Style / color notes<input name="style" maxlength="300"></label><label>Delivery estimate $<input name="delivery" type="number" min="0" max="100000" step=".01"></label><label>Assembly estimate $<input name="assembly" type="number" min="0" max="100000" step=".01"></label><label>Width (in)<input name="width" type="number" min=".1" step=".1"></label><label>Depth (in)<input name="depth" type="number" min=".1" step=".1"></label><label>Height (in)<input name="height" type="number" min=".1" step=".1"></label><label>Minimum work-surface depth needed (in)<input name="requiredDepth" type="number" min=".1" step=".1"></label><label>Assembly time / tools<input name="tools" placeholder="2 hours, screwdriver; confirm with seller" maxlength="300"></label><label>Delivery service / fees / timing<input name="service" placeholder="In-room, stair fees, delivery date…" maxlength="400"></label><label>Returns / payment / shipping minimum<input name="returns" maxlength="500" placeholder="Window, fees, accepted payments, free-shipping threshold"></label><label>Condition / authenticity evidence<input name="evidence" maxlength="500" placeholder="Receipt, maker marks, photos; user-entered, not verified"></label><label>Availability last confirmed by you<input name="confirmed" type="date"></label><label>Proposed pickup time<input name="pickup" type="datetime-local"></label><label>Move-out decision<select name="decision"><option value="buy">Buy / consider</option><option value="keep">Keep</option><option value="sell">Sell</option><option value="donate">Donate</option><option value="dispose">Recycle / dispose</option></select></label><label>Expected resale proceeds $<input name="resale" type="number" min="0" max="1000000" step=".01"></label><label>Move / handoff deadline<input name="deadline" type="date"></label><label>Ownership / settlement notes<input name="ownership" maxlength="500" placeholder="Who keeps it? Agree buyout separately."></label><label><input name="portable" type="checkbox"> Disassembles / portable (confirmed by you)</label></div><p class="note">Blank delivery or assembly costs are unknown, not free. Dimensions are a basic footprint check, not a guarantee of access or room layout.</p><div class="board-actions"><button type="submit" class="primary">Save piece</button><button id="cancel-item" type="button">Cancel</button></div></form></dialog>`;
function switchBoard(){for(const m of ['photo','planner','board']){$('#'+m+'-mode').hidden=m!=='board';$('#'+m+'-tab').setAttribute('aria-pressed',String(m==='board'));}render();}
$('#board-tab').onclick=switchBoard;for(const m of ['photo','planner'])$('#'+m+'-tab').addEventListener('click',()=>{$('#board-mode').hidden=true;$('#board-tab').setAttribute('aria-pressed','false');});
function fillBrief(){for(const [id,value] of Object.entries({'purpose':state.purpose,'horizon':state.horizon,'room-budget':state.budget,'tax-rate':state.tax,'people':state.people.join(', '),'room-width':state.space.width||'','room-depth':state.space.depth||'','room-door':state.space.door||'','access':state.space.access||''}))$('#'+id).value=value;}
$('#apply-brief').onclick=()=>{if(![...section.querySelectorAll('aside input')].every(el=>el.reportValidity()))return;state.purpose=$('#purpose').value;state.horizon=$('#horizon').value;state.budget=Number($('#room-budget').value);state.tax=Number($('#tax-rate').value);state.people=[...new Set($('#people').value.split(',').map(n=>n.trim()).filter(n=>n&&!['__proto__','constructor','prototype'].includes(n)))].slice(0,12);if(!state.people.length)state.people=['Me'];state.space={width:$('#room-width').value,depth:$('#room-depth').value,door:$('#room-door').value,access:$('#access').value};persist();render();status('Brief saved.');};
let editId=null;function edit(item){editId=item?.id||null;const f=$('#item-form');f.reset();for(const el of f.elements){if(!el.name)continue;if(el.type==='checkbox')el.checked=!!item?.[el.name];else el.value=item?.[el.name]??(el.name==='price'?'0':el.tagName==='SELECT'?el.options[0].value:'');}$('#item-title').textContent=item?'Edit piece':'Add a piece';$('#item-dialog').showModal();}
$('#add-item').onclick=()=>edit();$('#cancel-item').onclick=()=>$('#item-dialog').close();$('#item-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(data.url&&!/^https?:\/\//i.test(data.url)){status('Use an http or https listing link.');return;}const old=state.items.find(i=>i.id===editId);const item={...old,...data,id:editId||crypto.randomUUID(),portable:e.target.elements.portable.checked};if(old)state.items[state.items.indexOf(old)]=item;else state.items.push(item);persist();render();$('#item-dialog').close();};
function safeUrl(u){try{const url=new URL(u);return ['http:','https:'].includes(url.protocol)?url.href:'';}catch{return '';}}
function render(){const shopping=state.items.filter(i=>i.decision==='buy');const subtotal=shopping.reduce((s,i)=>s+totalCost(i,state.tax),0);const unknown=shopping.filter(i=>i.delivery===''||i.delivery==null||i.assembly===''||i.assembly==null).length;$('#board-summary').innerHTML=`<div class="board-total"><div><span class="eyebrow">PLANNED SPEND · ${shopping.length} PIECES</span><h2>${cash(subtotal)}</h2><p>${subtotal>state.budget?cash(subtotal-state.budget)+' over budget':cash(state.budget-subtotal)+' remaining'} · ${unknown} pieces with incomplete costs</p></div><div>Expected resale: ${cash(state.items.filter(i=>i.decision==='sell').reduce((s,i)=>s+Number(i.resale||0),0))}<p class="note">Resale estimates are not deducted from your buying budget.</p></div></div>`;const filter=$('#board-filter').value;let items=state.items.filter(i=>filter==='all'||filter==='buy'&&i.decision==='buy'||filter==='owned'&&(i.source==='owned'||i.decision!=='buy')||filter==='used'&&i.source==='used');if(state.horizon==='short')items=[...items].sort((a,b)=>Number(b.portable)-Number(a.portable));$('#board-items').innerHTML=items.length?items.map(i=>{const contributed=Object.values(i.contributions||{}).reduce((s,n)=>s+Number(n||0),0);return `<article class="board-piece"><div class="board-actions"><span class="badge">${esc(i.source)} · ${esc(i.decision)}</span>${i.portable?'<span class="badge">Portable</span>':''}</div><h3>${esc(i.name)}</h3><p>${esc(i.style||'Add style notes to compare the room as a set.')}</p><strong>${cash(totalCost(i,state.tax))} estimated total</strong><p class="note">Item ${cash(Number(i.price))} + estimated tax ${cash(Number(i.price)*state.tax/100)} · Delivery ${i.delivery===''||i.delivery==null?'unknown':cash(Number(i.delivery))} · Assembly ${i.assembly===''||i.assembly==null?'unknown':cash(Number(i.assembly))}</p><p><b>Will it fit?</b> ${esc(fitCheck(i,state.space))}${Number(i.requiredDepth)>0?'<br>Work surface: '+(!Number(i.depth)?'depth unknown':Number(i.depth)>=Number(i.requiredDepth)?'meets your minimum depth':'too shallow for your stated need'):''}</p><details><summary>Logistics, condition & move plan</summary><p>Dimensions: ${esc(i.width||'?')} × ${esc(i.depth||'?')} × ${esc(i.height||'?')} in</p><p>Delivery: ${esc(i.service||'Not checked')}</p><p>Assembly: ${esc(i.tools||'Time and tools not checked')}</p><p>Returns / payment: ${esc(i.returns||'Not checked')}</p><p>Condition / evidence: ${esc(i.evidence||'No verification evidence entered')}</p><p>Availability: ${i.confirmed?'Last confirmed by you '+esc(i.confirmed):'Not confirmed'} · Pickup proposal: ${esc(i.pickup||'Not arranged')} (confirm with seller)</p><p>Deadline: ${esc(i.deadline||'Not set')} · Resale estimate: ${cash(Number(i.resale||0))}</p><p>Ownership: ${esc(i.ownership||'Agree who keeps the piece and any settlement.')}</p></details><div class="household">${state.people.map((name,index)=>`<label>${esc(name)}<select data-vote="${esc(i.id)}" data-person="${index}">${['Undecided','Yes','Maybe','No'].map(v=>`<option ${i.votes?.[name]===v?'selected':''}>${v}</option>`).join('')}</select><span>Contributed $</span><input aria-label="${esc(name)} contribution for ${esc(i.name)}" type="number" min="0" step=".01" data-contribution="${esc(i.id)}" data-person="${index}" value="${esc(i.contributions?.[name]||'')}"></label>`).join('')}</div><p class="note">Recorded contributions: ${cash(contributed)} · ${contributed>totalCost(i,state.tax)?'Overfunded by '+cash(contributed-totalCost(i,state.tax)):'Unfunded '+cash(totalCost(i,state.tax)-contributed)}. Records only; no payments or buyouts are processed.</p><div class="board-actions">${safeUrl(i.url)?`<a href="${esc(safeUrl(i.url))}" target="_blank" rel="noopener noreferrer">Open seller ↗</a>`:''}<button data-edit="${esc(i.id)}">Edit details</button><button data-delete="${esc(i.id)}">Remove</button></div></article>`;}).join(''):'<div class="photo-empty"><h2>Start with a piece, or a whole room.</h2><p>Save catalog finds, add a secondhand listing or inventory furniture you own. Compare household votes and costs here.</p></div>';}
$('#board-filter').onchange=render;$('#board-items').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.edit)edit(state.items.find(i=>i.id===b.dataset.edit));if(b.dataset.delete){state.items=state.items.filter(i=>i.id!==b.dataset.delete);persist();render();}};$('#board-items').onchange=e=>{const el=e.target;const id=el.dataset.vote||el.dataset.contribution;if(!id)return;const item=state.items.find(i=>i.id===id),person=state.people[Number(el.dataset.person)];if(!item||!person||!el.reportValidity())return;if(el.dataset.vote){item.votes??={};item.votes[person]=el.value;}else{item.contributions??={};item.contributions[person]=Number(el.value);}persist();render();};
function saveProduct(p){if(state.items.some(i=>i.catalogId===p.id)){status('That piece is already on your board.');return;}state.items.push({id:crypto.randomUUID(),catalogId:p.id,name:p.name+' '+p.type,price:p.price,url:p.url,style:p.detail,category:p.category,source:'new',decision:'buy',delivery:'',assembly:''});persist();render();}
window.addEventListener('roomedit-save',e=>{const p=catalog.find(p=>p.id===e.detail);if(p){saveProduct(p);status('Saved '+p.name+' to your room board.');}});
$('#starter').onclick=()=>{const groups={living:['sofa','table','lamp'],work:['desk','chair','lamp'],sleep:['bed','table','lamp'],small:['chair','storage','lamp']}[state.purpose];let remaining=Math.max(0,state.budget-state.items.filter(i=>i.decision==='buy').reduce((s,i)=>s+totalCost(i,state.tax),0));let count=0;for(const cat of groups){if(state.items.some(i=>i.category===cat&&i.decision==='buy'))continue;const p=catalog.filter(p=>p.category===cat&&!state.items.some(i=>i.catalogId===p.id)).sort((a,b)=>a.price-b.price)[0];if(p&&p.price*(1+state.tax/100)<=remaining){saveProduct(p);remaining-=p.price*(1+state.tax/100);count++;}}status(count?`Added ${count} starter pieces. Check delivery and assembly costs; a catalog chair is not an ergonomic certification.`:'No additional starter pieces fit the remaining budget.');};
$('#export-board').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='roomedit-board.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function importBoard(b){if(!validateBoard(b))throw Error();state={...state,...b,space:b.space||{}};persist();fillBrief();render();switchBoard();}
$('#import-board').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>500000)throw Error();const b=JSON.parse(await file.text());if(state.items.length&&!confirm('Replace your current board with this imported snapshot?'))return;importBoard(b);status('Board imported.');}catch{status('Could not import this board. Choose a valid Room Edit JSON export under 500 KB.');}e.target.value='';};
$('#share-board').onclick=async()=>{const data=btoa(unescape(encodeURIComponent(JSON.stringify(state))));if(data.length>16000){status('This board is too large for a link. Export it instead.');return;}const url=location.origin+location.pathname+'#board='+data;try{await navigator.clipboard.writeText(url);status('Snapshot link copied. It includes names, contributions and listing notes. Recipients need site access; changes do not sync.');}catch{status('Clipboard unavailable. Export your board to share it.');}};
fillBrief();render();if(location.hash.startsWith('#board=')){try{const b=JSON.parse(decodeURIComponent(escape(atob(location.hash.slice(7)))));if(validateBoard(b)&&confirm('Load the shared board snapshot? This replaces your local board.'))importBoard(b);}catch{status('The shared board link could not be read.');}history.replaceState(null,'',location.pathname);}

window.addEventListener('roomedit-market-save',e=>{const p=e.detail;if(state.items.some(i=>i.marketId===p.id)){status('This marketplace piece is already on your board.');return;}state.items.push({id:crypto.randomUUID(),marketId:p.id,name:p.name+' (demo listing)',price:p.price,source:'used',decision:'buy',category:p.category,width:p.width,depth:p.depth,height:p.height,portable:p.portable,delivery:'',assembly:'',evidence:p.condition+' · Demo seller: '+p.seller+' · Not verified',service:p.platform+' · '+p.area+' · Pickup preference: '+(p.pickupPreference||'not selected')+' (not booked)',style:'Marketplace demo'});persist();render();status('Marketplace piece saved. Pickup is a preference, not a booking.');});
